using System.Linq; using System.Data.Entity; using System.Web.Mvc; using MaSV_LTW_MyStore.Models; namespace MaSV_LTW_MyStore.Controllers { public class HomeController:Controller { private StoreContext db=new StoreContext(); public ActionResult Index(){ ViewBag.Categories=db.Categories.ToList(); return View(db.Products.Include(p=>p.Category).OrderByDescending(p=>p.ProductID).Take(8).ToList()); } protected override void Dispose(bool disposing){if(disposing)db.Dispose();base.Dispose(disposing);} } }